@Path("/users")
public class UserResource {
    @Inject UserDirectory users;                          // domain entry point

    @GET @Path("/{id}") @Produces(MediaType.APPLICATION_JSON)
    public Response get(@PathParam("id") long id) {       // action
        return users.find(id)
            .map(u -> Response.ok(new UserDto(u)).build())   // responder
            .orElseGet(() -> Response.status(404).build());
    }
}

