RouterFunction<ServerResponse> routes(UserHandler h) {
    return route(GET("/users/{id}"), h::getUser);
}

Mono<ServerResponse> getUser(ServerRequest req) {            // action
    long id = Long.parseLong(req.pathVariable("id"));
    return users.find(id)                                    // domain
        .flatMap(u -> ok().contentType(APPLICATION_JSON)
                          .bodyValue(new UserDto(u)))        // responder
        .switchIfEmpty(ServerResponse.notFound().build());
}
